#!/usr/bin/env node
// Generates veronica-giuliani-story-i18n-data.js: window.VERONICA_STORY_<LANG> globals for the
// ten agent-translated locales, built from the localized catalog (content/books/.../<lang>.json)
// with per-page evidence type/sources and media fields inherited from book.json (EN structural
// source). The byte-exact EN/AR globals in veronica-giuliani-story-data.js are untouched.
// --check: verify the generated file is up to date without writing.
import fs from 'node:fs';
import path from 'node:path';
const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '../..');
const DIR = 'content/books/veronica-giuliani-story';
const OUT = 'veronica-giuliani-story-i18n-data.js';
const LOCALES = ['fr', 'es', 'pt', 'it', 'de', 'pl', 'ru', 'hi', 'th', 'zh-Hans'];
const GLOBALS = { fr: 'VERONICA_STORY_FR', es: 'VERONICA_STORY_ES', pt: 'VERONICA_STORY_PT', it: 'VERONICA_STORY_IT', de: 'VERONICA_STORY_DE', pl: 'VERONICA_STORY_PL', ru: 'VERONICA_STORY_RU', hi: 'VERONICA_STORY_HI', th: 'VERONICA_STORY_TH', 'zh-Hans': 'VERONICA_STORY_ZH_HANS' };
const book = JSON.parse(fs.readFileSync(path.join(ROOT, DIR, 'book.json'), 'utf8'));
const en = JSON.parse(fs.readFileSync(path.join(ROOT, DIR, 'en.json'), 'utf8'));
// Structural truth is book.json (scene, image, audio, reflection, evidence types and
// source ids); prose is the per-locale catalog. No runtime file is an input.
const assetPath = Object.fromEntries(book.assets.map(a => [a.id, './' + a.path]));
const structure = book.pages.map(p => ({
  illustration: assetPath[p.image], scene: p.scene,
  audio: p.audio && p.audio.src ? p.audio.src : '', reflection: p.reflection === true,
  evidence: p.evidence.map(e => ({ type: e.type, claim: e.claim, sources: e.sources }))
}));
const buildPages = (catalog, claimsOf) => catalog.pages.map((p, i) => {
  const s = structure[i];
  if (p.id !== book.pages[i].id) throw new Error(`${catalog.locale} page ${i + 1}: id order mismatch`);
  return {
    illustration: s.illustration, title: p.title, body: p.body, prayer: p.prayer, heart: p.heart,
    scene: s.scene, audio: s.audio, reflection: s.reflection,
    evidence: s.evidence.map((e, j) => ({ type: e.type, claim: claimsOf(p)[j] || claimsOf(p)[0] || e.claim, sources: e.sources }))
  };
});
// EN claims are authored in book.json; localized claims live in each catalog's evidenceClaims.
const enPages = buildPages(en, p => book.pages[en.pages.indexOf(p)].evidence.map(e => e.claim));
const ar = JSON.parse(fs.readFileSync(path.join(ROOT, DIR, 'ar.json'), 'utf8'));
const arPages = buildPages(ar, p => (ar.evidenceClaims || {})[p.id] || []);
const enChunks = ['// GENERATED by scripts/books/build-veronica-i18n-data.mjs - do not edit by hand.',
  '// EN prose from en.json (pin-reviewed) and AR prose from ar.json (pinned draft); structure from book.json.',
  `window.VERONICA_STORY_EN = ${JSON.stringify(enPages, null, 2)};\n`,
  `window.VERONICA_STORY_AR = ${JSON.stringify(arPages, null, 2)};\n`];
const chunks = ['// GENERATED by scripts/books/build-veronica-i18n-data.mjs - do not edit by hand.',
  '// Agent-translated editions (review: agent-translated); EN/AR live in veronica-giuliani-story-data.js.'];
for (const loc of LOCALES) {
  const t = JSON.parse(fs.readFileSync(path.join(ROOT, DIR, `${loc}.json`), 'utf8'));
  if (t.locale !== loc || t.review !== 'agent-translated' || t.pages.length !== en.pages.length) throw new Error(`${loc}: catalog shape mismatch`);
  const claims = p => {
    const c = (t.evidenceClaims || {})[p.id] || [];
    if (!c.length) throw new Error(`${loc} ${p.id}: missing evidence claims`);
    return c;
  };
  chunks.push(`window.${GLOBALS[loc]} = ${JSON.stringify(buildPages(t, claims), null, 1)};\n`);
}
const EN_OUT = 'veronica-giuliani-story-data.js';
const pairs = [[EN_OUT, enChunks.join('\n')], [OUT, chunks.join('\n')]];
const check = process.argv.includes('--check');
let stale = 0;
for (const [file, text] of pairs) {
  const current = fs.existsSync(path.join(ROOT, file)) ? fs.readFileSync(path.join(ROOT, file), 'utf8') : '';
  if (current !== text) {
    if (check) { console.error(file + ': out of date'); stale++; }
    else { fs.writeFileSync(path.join(ROOT, file), text); console.log(file + ': written'); }
  } else console.log(file + ': up to date');
}
process.exit(check && stale ? 1 : 0);
